// Validate input
const body = $input.first().json.body ?? $input.first().json;
const story_id = body.story_id;
const partner_id = body.partner_id;
const page_intent = body.page_intent ?? 'landing';
const existing_canvas = body.existing_canvas ?? null;

if (!story_id || !partner_id) {
  throw new Error('story_id and partner_id are required');
}

// Inject creativity seed — CRITICAL for anti-stereotypical output
const creativity_seed = Math.random();

return [{ json: { story_id, partner_id, page_intent, existing_canvas, creativity_seed } }];

// Load design profile via MCP
const { partner_id } = $input.first().json;

const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const response = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 1,
    method: 'tools/call',
    params: {
      name: 'get_design_profile',
      arguments: { partner_id }
    }
  })
});

const result = await response.json();
const profile = result?.result?.content?.[0]?.text ?? null;
const designProfile = profile ? JSON.parse(profile) : null;

return [{ json: { ...$input.first().json, design_profile: designProfile?.profile ?? {} } }];

// Load compose_context for Occipitum agent
const { story_id, partner_id, page_intent } = $input.first().json;

const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const response = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 2,
    method: 'tools/call',
    params: {
      name: 'compose_context',
      arguments: {
        agent_slug: 'occipitum',
        context_profile_slug: 'planning_heavy',
        query: `Design canvas for ${page_intent} page, story ${story_id}`
      }
    }
  })
});

const result = await response.json();
const context = result?.result?.content?.[0]?.text ?? '';

return [{ json: { ...$input.first().json, agent_context: context } }];

// Search design patterns with ANTI-STEREOTYPICAL selection
// Top-15 recall, random 5 pick (never deterministic top-5)
const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const { design_profile, creativity_seed, page_intent } = $input.first().json;
const vibeWords = design_profile?.style_preferences?.vibe_words ?? ['modern', 'clean'];

// Search patterns
const patternResponse = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 3,
    method: 'tools/call',
    params: {
      name: 'search_knowledge_v2',
      arguments: {
        query: `design pattern ${page_intent} ${vibeWords.join(' ')}`,
        tags: ['occipitum'],
        limit: 15
      }
    }
  })
});

const patternResult = await patternResponse.json();
const allPatterns = JSON.parse(patternResult?.result?.content?.[0]?.text ?? '[]');

// ANTI-STEREOTYPE: Random 5 from top-15 (not deterministic top-5)
const shuffled = allPatterns
  .map(p => ({ ...p, _sort: Math.random() }))
  .sort((a, b) => a._sort - b._sort)
  .slice(0, 5);

// Search anti-patterns (always load all)
const antiPatternResponse = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 4,
    method: 'tools/call',
    params: {
      name: 'search_knowledge_v2',
      arguments: {
        query: 'design anti-pattern blacklist',
        tags: ['occipitum', 'antipattern'],
        limit: 20
      }
    }
  })
});

const antiPatternResult = await antiPatternResponse.json();
const antiPatterns = JSON.parse(antiPatternResult?.result?.content?.[0]?.text ?? '[]');

return [{ json: {
  ...$input.first().json,
  selected_patterns: shuffled,
  anti_patterns: antiPatterns
} }];

// Prepare LLM prompt for canvas generation
const data = $input.first().json;

// Creativity seed determines style band:
// 0-0.3 → experimental/brutalist
// 0.3-0.6 → editorial/storytelling
// 0.6-1.0 → luxury/immersive
const seed = data.creativity_seed;
let styleBand;
if (seed < 0.3) styleBand = 'experimental_brutalist';
else if (seed < 0.6) styleBand = 'editorial_storytelling';
else styleBand = 'luxury_immersive';

const systemPrompt = `You are OCCIPITUM — AISHA's visual cortex.

Your mission: Generate a GrapeJS ProjectData JSON for a ${data.page_intent} page.

STYLE BAND (from creativity_seed ${seed.toFixed(3)}): ${styleBand}

DESIGN PROFILE:
${JSON.stringify(data.design_profile, null, 2)}

SELECTED PATTERNS (use as inspiration, don't copy literally):
${data.selected_patterns.map(p => '- ' + (p.title ?? p.name ?? 'pattern')).join('\n')}

ABSOLUTE BLACKLIST — NEVER use:
${data.anti_patterns.map(p => '- ' + (p.title ?? p.name ?? 'anti-pattern')).join('\n')}

AGENT CONTEXT:
${data.agent_context}

OUTPUT FORMAT:
Return ONLY valid JSON with this structure:
{
  "pages": [{ "component": "<body>...</body>" }],
  "styles": [...],
  "_occipitum_rationale": {
    "style_band": "${styleBand}",
    "creativity_seed": ${seed.toFixed(3)},
    "patterns_used": [...],
    "anti_patterns_avoided": [...],
    "design_reasoning": "..."
  }
}

RULES:
1. The HTML in pages[0].component MUST use Tailwind CSS classes
2. NEVER use generic hero+CTA layout
3. NEVER use hamburger menu on desktop
4. NEVER use cookie-cutter card grids
5. Each section must have a clear visual rhythm
6. Use personality from design_profile to drive color, typography, spacing
7. Include at least 2 unexpected visual elements (asymmetry, overlapping, kinetic hints)
8. The design must tell a story, not just display information`;

const userPrompt = `Generate a ${data.page_intent} page design for this partner.
Existing canvas: ${data.existing_canvas ? 'yes (will be replaced)' : 'fresh start'}
Creativity seed: ${seed.toFixed(3)} → ${styleBand}`;

return [{ json: {
  ...data,
  style_band: styleBand,
  system_prompt: systemPrompt,
  user_prompt: userPrompt
} }];

// Parse LLM output into valid GrapeJS ProjectData
const llmOutput = $input.first().json.response ?? $input.first().json.text ?? '';

// Extract JSON from potentially markdown-wrapped response
let projectData;
try {
  const jsonMatch = llmOutput.match(/```(?:json)?\s*([\s\S]*?)```/);
  const jsonStr = jsonMatch ? jsonMatch[1].trim() : llmOutput.trim();
  projectData = JSON.parse(jsonStr);
} catch (e) {
  // Fallback: try direct parse
  try {
    projectData = JSON.parse(llmOutput);
  } catch {
    throw new Error('Failed to parse LLM output as valid GrapeJS ProjectData: ' + e.message);
  }
}

// Validate minimal structure
if (!projectData.pages || !Array.isArray(projectData.pages)) {
  throw new Error('Invalid ProjectData: missing pages array');
}

const { story_id, partner_id, creativity_seed, style_band } = $input.first().json;

return [{ json: {
  story_id,
  partner_id,
  creativity_seed,
  style_band,
  project_data: projectData,
  rationale: projectData._occipitum_rationale ?? {}
} }];

// Store as personality signal for Hippocampus memory
const { partner_id, story_id, style_band, rationale } = $input.first().json;

// Resolve partner_id → user_id (personality_signals requires auth user UUID)
let userId = null;
try {
  const lookupRes = await fetch($env.AISHA_POSTGREST_URL + '/rest/v1/partner_profiles?id=eq.' + partner_id + '&select=user_id', {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
      'apikey': $env.AISHA_POSTGREST_ANON_KEY
    }
  });
  const rows = await lookupRes.json();
  if (rows.length > 0) userId = rows[0].user_id;
} catch (e) {
  // Non-blocking — continue without signal
}

if (userId) {
  await fetch($env.AISHA_POSTGREST_URL + '/rest/v1/rpc/fn_capture_personality_signal', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
      'apikey': $env.AISHA_POSTGREST_ANON_KEY
    },
    body: JSON.stringify({
      p_user_id: userId,
      p_signal_type: 'design_proposal_generated',
      p_value: { style_band, story_id, reasoning: rationale.design_reasoning ?? '' },
      p_weight: 0.6
    })
  });
}

return [{ json: $input.first().json }];

// Broadcast proposal to StoryLoop canvas via Supabase Realtime HTTP API
const { story_id, partner_id, project_data, rationale, creativity_seed, style_band } = $input.first().json;

const realtimeUrl = $env.AISHA_POSTGREST_URL + '/realtime/v1/api/broadcast';

try {
  await fetch(realtimeUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${$env.AISHA_POSTGREST_SERVICE_KEY}`,
      'apikey': $env.AISHA_POSTGREST_ANON_KEY
    },
    body: JSON.stringify({
      messages: [{
        topic: `story:${story_id}:canvas`,
        event: 'agent_activity',
        payload: {
          id: `occipitum-${Date.now()}`,
          agent: 'occipitum',
          type: 'occipitum_proposal',
          timestamp: new Date().toISOString(),
          project_data,
          rationale,
          creativity_seed,
          style_band
        }
      }]
    })
  });
} catch (e) {
  // Non-blocking — proposal is still returned in response
}

return [{ json: {
  success: true,
  signal: 'occipitum_proposal',
  story_id,
  partner_id,
  style_band,
  creativity_seed,
  rationale,
  project_data
} }];
